from pathlib import Path
HERE=Path(__file__).resolve().parent
def build():
 h=(HERE.parent/'ops/tpl.html').read_text(encoding='utf-8')
 strings=h[h.index('const S='):h.index('const G=')]
 card=h[h.index('function oCard(o,mode)'):h.index('function rWaiter(el)')]
 lines=h[h.index('function orderLines('):h.index('function wishHTML(')]
 result = '// Generated from original ops/tpl.html incoming card. New submissions only.\nwindow.guestIncoming=(()=>{function cards(submissions,me){\nconst esc=v=>String(v??\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\nconst ST={lang:\'ru\',me,shift:{[me]:true},bills:{}},M={},NEW_LATE_MS=45000,REORDER_MS=40000,LANGNAME={ru:\'Русский\',vi:\'Tiếng Việt\',en:\'English\',de:\'Deutsch\'};\nconst t=k=>S.ru[k]||k,forMe=()=>true,wname=()=>\'\',pendingServe=()=>false,prepSummary=()=>\'\',wishHTML=()=>\'\',vnd=n=>Number(n).toLocaleString(\'ru-RU\')+\' ₫\',nm=(id,l)=>M[id][l]||M[id].vi||\'\',tot=o=>o.items.reduce((n,i)=>n+M[i.mid].p*i.qty,0),stLabel=()=>t(\'sNew\'),since=ts=>Math.max(0,Math.floor((Date.now()-ts)/60000))+\' мин\',mmss=ts=>Math.max(0,Math.floor((Date.now()-ts)/60000))+\':\'+String(Math.max(0,Math.floor((Date.now()-ts)/1000))%60).padStart(2,\'0\');\n' +strings+lines+card+'\nreturn submissions.map(g=>{const items=[];for(const ck of g.checks){for(const [n,i] of ck.items.entries()){const mid=ck.id+\':\'+n;M[mid]={...i.names,p:i.price};items.push({mid,qty:i.quantity,note:(g.checks.length>1?\'Чек \'+ck.label+\'. \':\'\')+(i.note||\'\')})}}const o={id:esc(g.id),no:esc(g.id.slice(0,8)),status:\'new\',src:\'qr\',table:esc(g.table),createdAt:Date.parse(g.created_at),check:g.checks.length===1?g.checks[0].label:\'\',lang:g.lang,items};return oCard(o).replace(\'data-a="accept"\',\'data-guest-accept="\'+esc(g.id)+\'"\')}).join(\'\');\n}return {cards};})();\n'
 return result.replace('return oCard(o).replace(\'data-a="accept"\',\'data-guest-accept="\'+esc(g.id)+\'"\')','return oCard(o).replace(\'data-a="accept"\',\'data-guest-accept="\'+esc(g.id)+\'"\').replace(\'</button>\',\'</button><button type="button" data-guest-reject="\'+esc(g.id)+\'">Отклонить</button>\')')
if __name__=='__main__':(HERE/'incoming-ui.js').write_text(build(),encoding='utf-8')
